function bind(){app.querySelectorAll(".tab").forEach(t=>{t.onclick=e=>{if(!e.target.closest(".close"))activate(t.dataset.k,+t.dataset.i)};t.onkeydown=e=>{if(e.target.closest(".close"))return;let a=[...app.querySelectorAll('.tab[data-k="'+t.dataset.k+'"]')],p=a.indexOf(t);if(e.key==="ArrowLeft"||e.key==="ArrowRight"){e.preventDefault();a[(p+(e.key==="ArrowRight"?1:-1)+a.length)%a.length].focus()}if(e.key==="Enter"||e.key===" "){e.preventDefault();activate(t.dataset.k,+t.dataset.i)}}});app.querySelectorAll(".close").forEach(x=>{x.onclick=e=>{e.stopPropagation();close(+x.dataset.close)};x.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();e.stopPropagation();close(+x.dataset.close)}}});app.querySelectorAll(".arrow").forEach(b=>b.onclick=()=>b.parentElement.querySelector(".track").scrollBy({left:+b.dataset.m*(b.dataset.k==="doc"?140:112),behavior:"smooth"}));app.querySelectorAll(".track").forEach(t=>t.onwheel=e=>{e.preventDefault();t.scrollLeft+=e.deltaY},{passive:false});app.querySelectorAll(".count").forEach(b=>b.onclick=()=>{if(b.dataset.count==="doc"){chooser=true;render()}else{pop=!pop;render(pop?".choice":'[data-count="item"]')}});app.querySelector(".back")?.addEventListener("click",dismiss);app.querySelectorAll(".card").forEach(x=>x.onclick=()=>{sel=+x.dataset.card;chooser=false;render('[data-k="doc"][data-i="'+sel+'"]')});app.querySelectorAll(".choice").forEach(x=>x.onclick=()=>{docs[sel].sel=+x.dataset.item;pop=false;render('[data-count="item"]')})}
document.addEventListener("keydown",e=>{if(e.key==="Escape"){if(chooser){e.preventDefault();dismiss()}else if(pop){e.preventDefault();pop=false;render('[data-count="item"]')}}});addEventListener("resize",()=>render());render();
